import pytest


def parity(x: int) -> bool:
    """True when the byte x (an int from 0 to 255) has an odd number of set bits."""
    return bin(x).count("1") % 2 == 1


def test_parity_zero() -> None:
    assert parity(0) is False


def test_parity_single_bits() -> None:
    for i in range(8):
        assert parity(1 << i) is True


def test_parity_two_bits() -> None:
    assert parity(0b11) is False
    assert parity(0b10000001) is False
    assert parity(0b01010000) is False


def test_parity_three_bits() -> None:
    assert parity(0b111) is True
    assert parity(0b10100100) is True


def test_parity_all_ones() -> None:
    assert parity(255) is False


def test_parity_known_values() -> None:
    assert parity(1) is True
    assert parity(2) is True
    assert parity(3) is False
    assert parity(254) is True
    assert parity(128) is True


def test_parity_matches_bit_count_for_all_bytes() -> None:
    for x in range(256):
        assert parity(x) is (bin(x).count("1") % 2 == 1)


@pytest.mark.parametrize(
    ("x", "expected"),
    [
        (0, False),
        (1, True),
        (7, True),
        (15, False),
        (127, True),
        (255, False),
    ],
)
def test_parity_parametrized(x: int, expected: bool) -> None:
    assert parity(x) is expected

